package com.example.rokidgeminisecretary;
import android.app.*;import android.content.*;import android.net.Uri;import android.view.*;import android.widget.*;import org.json.*;import java.util.UUID;
/** Conversation-side status and on-demand player. Never autoplay audio or hold video in the UI heap. */
final class GeneratedVideoPanel {
 private final Activity host;private final LinearLayout root;private final TextView status;private String signature="";private AlertDialog player;
 GeneratedVideoPanel(Activity host){this.host=host;root=new LinearLayout(host);root.setOrientation(1);Button button=new Button(host);button.setText("動画生成・生成動画一覧");button.setOnClickListener(v->list());root.addView(button);status=new TextView(host);status.setTextSize(12);status.setText("会話から「ロキが手を振る動画を作って」と依頼できます。8秒・720p。指示・元画像をGeminiへ送信し、動画API利用料が発生します。");root.addView(status);refresh();}
 View view(){return root;}void close(){if(player!=null)player.dismiss();player=null;}
 static String label(JSONObject j){switch(j.optString("state")){case "queued":return "動画：受付済み";case "submitting":return "動画APIへ受付中…";case "running":return "動画生成中… 会話を続けられます";case "downloading":return "完成動画をダウンロード中…";case "saving":return "動画を保存中…";case "completed":return j.has("galleryUri")?"動画完成・ギャラリー保存済み":"動画完成・ギャラリー保存を再試行してください";case "paused":return "結果確認を休止中："+j.optString("error",j.optString("statusError"));default:return "動画生成失敗："+j.optString("error");}}
 void refresh(){try{JSONArray jobs=VideoGeneration.list(host);String next=jobs.toString();if(next.equals(signature))return;signature=next;if(jobs.length()==0)status.setText("会話から動画を依頼できます。8秒・720p。動画API利用料が発生します。");if(jobs.length()>0){JSONObject j=jobs.getJSONObject(0);status.setText(label(j)+"\n"+j.optString("prompt"));}}catch(Exception e){status.setText("動画の状態を取得できません");}}
 static void prompt(Activity host,String parent){EditText input=new EditText(host);input.setMinLines(2);input.setHint(parent.isEmpty()?"例：ロキが笑顔で手を振る動画を作って":"例：この画像を、自然にまばたきする動画にして");new AlertDialog.Builder(host).setTitle("8秒の動画を生成").setMessage("指示・元画像をGeminiへ送信します。ロキ自身の依頼では登録画像を参照します。動画API利用料が発生します。").setView(input).setNegativeButton("取消",null).setPositiveButton("動画を生成",(d,w)->{try{VideoGeneration.enqueue(host,UUID.randomUUID().toString(),input.getText().toString(),null,parent);Toast.makeText(host,"動画を受け付けました。会話を続けられます",0).show();}catch(Exception e){Toast.makeText(host,e.getMessage(),1).show();}}).show();}
 void list(){try{JSONArray jobs=VideoGeneration.list(host);String[] labels=new String[jobs.length()];for(int i=0;i<labels.length;i++){JSONObject j=jobs.getJSONObject(i);labels[i]=label(j)+"\n"+j.optString("prompt");}new AlertDialog.Builder(host).setTitle("生成動画（新しい順）").setItems(labels,(d,i)->{try{show(jobs.getJSONObject(i));}catch(Exception e){Toast.makeText(host,"動画を開けません",1).show();}}).setPositiveButton("新しく生成",(d,w)->prompt(host,"")).setNegativeButton("閉じる",null).show();}catch(Exception e){Toast.makeText(host,"一覧を取得できません",1).show();}}
 void show(JSONObject job)throws Exception{String id=job.getString("id");if("completed".equals(job.optString("state"))){new AlertDialog.Builder(host).setTitle("生成動画").setMessage(job.optString("prompt")+"\n"+label(job)).setPositiveButton("再生",(d,w)->play(job)).setNeutralButton("ギャラリーに保存",(d,w)->new Thread(()->{try{VideoGeneration.gallery(host,id);host.runOnUiThread(()->{refresh();Toast.makeText(host,"保存を確認しました",0).show();});}catch(Exception e){host.runOnUiThread(()->Toast.makeText(host,"動画の保存を完了できません",1).show());}},"LokiVideoGallery").start()).setNegativeButton("ロキ内から削除",(d,w)->remove(id)).show();}else{AlertDialog.Builder b=new AlertDialog.Builder(host).setTitle("動画の状態").setMessage(label(job)).setNegativeButton("閉じる",null);if(job.optBoolean("canResume"))b.setPositiveButton("結果確認を再開",(d,w)->{try{VideoGeneration.resume(host,id);refresh();}catch(Exception e){Toast.makeText(host,e.getMessage(),1).show();}});if(!VideoGeneration.active(job.optString("state")))b.setNeutralButton("ロキ内から削除",(d,w)->remove(id));b.show();}}
 void play(JSONObject job){String uri=job.optString("galleryUri");if(uri.isEmpty()){Toast.makeText(host,"先にギャラリーへ保存してください",1).show();return;}close();VideoView video=new VideoView(host);video.setContentDescription("生成動画プレーヤー");MediaController controls=new MediaController(host);video.setMediaController(controls);LinearLayout frame=new LinearLayout(host);frame.setOrientation(1);frame.addView(video,new LinearLayout.LayoutParams(-1,Math.round(330*host.getResources().getDisplayMetrics().density)));player=new AlertDialog.Builder(host).setTitle("生成動画を再生").setView(frame).setNegativeButton("閉じる",null).create();player.setOnDismissListener(d->video.stopPlayback());video.setOnPreparedListener(p->video.start());video.setOnErrorListener((p,a,b)->{Toast.makeText(host,"動画を再生できません。ギャラリーで削除した場合は保存し直してください",1).show();return true;});player.show();video.setVideoURI(Uri.parse(uri));}
 void remove(String id){new AlertDialog.Builder(host).setMessage("ロキ内の動画・生成指示を削除します。ギャラリーに保存した動画は残ります。APIへの生成依頼の取消にはなりません。").setPositiveButton("削除",(d,w)->{try{VideoGeneration.delete(host,id);signature="";refresh();}catch(Exception e){Toast.makeText(host,e.getMessage(),1).show();}}).setNegativeButton("取消",null).show();}
}
